<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import{computed,ref}from'vue';import AuthenticatedLayout from'../../Layouts/AuthenticatedLayout.vue';import InventorySkuCombobox from'./components/InventorySkuCombobox.vue';type Item={id:number;product:{id:number;sku:string;name:string};quantity_on_hand:number;quantity_reserved:number;quantity_available:number;stock_status:'out_of_stock'|'low_stock'|'in_stock';stock_status_label:string;inbound_at:string|null;stay_days:number|null;location:string|null;standard_qoh:number|null;expected_restock_qty:number;replenishment:{policy_status:'unconfigured'|'no_demand'|'reorder'|'healthy';policy_label:string;shipped_90d_qty:number;days_of_cover:number|null;recommended_restock_qty:number|null}};type W={id:number;slug:string;code:string;name:string;country_code:string|null;address_line1:string|null;address_line2:string|null;city:string|null;state_region:string|null;postal_code:string|null;timezone:string|null;type:string;ownership_type:'owned'|'external';is_domestic:boolean;is_active:boolean;priority:number;fulfillment_available_on:string|null;fulfillment_state:'preparing'|'awaiting_inventory'|'ready';fulfillment_state_label:string;replenishment_lead_time_days:number|null;replenishment_safety_stock_days:number|null;replenishment_target_cover_days:number|null;billing_markdown:string|null;service_regions:string[];inventories:Item[]};type ClearanceProduct={id:number;product:{id:number;sku:string;name:string};priority:number;quantity_on_hand:number|null;quantity_reserved:number|null;quantity_available:number|null;status:'available'|'out_of_stock'|'unknown';status_label:string};type ClearanceCandidate={product_id:number;sku:string;name:string;quantity_available:number;already_clearance:boolean};const props=defineProps<{warehouse:W;clearanceProducts:ClearanceProduct[];clearanceCandidates:ClearanceCandidate[];canOperate:boolean;canManage:boolean}>();const breadcrumbs=[{label:'BYL ERP',href:'/dashboard'},{label:'库存',href:'/inventory'},{label:'仓库清单',href:'/inventory/list'},props.warehouse.name];const meta=useForm({name:props.warehouse.name,code:props.warehouse.code,country_code:props.warehouse.country_code||'',address_line1:props.warehouse.address_line1||'',address_line2:props.warehouse.address_line2||'',city:props.warehouse.city||'',state_region:props.warehouse.state_region||'',postal_code:props.warehouse.postal_code||'',timezone:props.warehouse.timezone||'',type:props.warehouse.type,ownership_type:props.warehouse.ownership_type,is_domestic:props.warehouse.is_domestic,is_active:props.warehouse.is_active,priority:props.warehouse.priority,fulfillment_available_on:props.warehouse.fulfillment_available_on||'',replenishment_lead_time_days:props.warehouse.replenishment_lead_time_days,replenishment_safety_stock_days:props.warehouse.replenishment_safety_stock_days,replenishment_target_cover_days:props.warehouse.replenishment_target_cover_days});const billing=useForm({billing_markdown:props.warehouse.billing_markdown||''});const regions=useForm({country_codes:props.warehouse.service_regions.join(', ')} as any);const stock=useForm({product_id:null as number|null,sku:'',quantity_on_hand:0,quantity_reserved:0,inbound_at:'',location:'',standard_qoh:null as number|null,expected_restock_qty:0});const productTab=ref<'inventory'|'clearance'>('inventory');const clearanceQuery=ref('');const clearance=useForm({product_ids:[] as number[]});const filteredClearanceCandidates=computed(()=>props.clearanceCandidates.filter(c=>!c.already_clearance&&(!clearanceQuery.value||`${c.sku} ${c.name}`.toLowerCase().includes(clearanceQuery.value.toLowerCase()))));const saveMeta=()=>meta.patch(`/inventory/${props.warehouse.slug}`);const saveBilling=()=>billing.patch(`/inventory/${props.warehouse.slug}/billing`);const saveRegions=()=>{const codes=String(regions.country_codes||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);regions.transform(()=>({country_codes:codes})).patch(`/inventory/${props.warehouse.slug}/regions`,{onFinish:()=>regions.defaults()})};const addStock=()=>stock.transform(d=>({product_id:d.product_id,quantity_on_hand:d.quantity_on_hand,quantity_reserved:d.quantity_reserved,inbound_at:d.inbound_at||null,location:d.location||null,standard_qoh:d.standard_qoh,expected_restock_qty:d.expected_restock_qty})).post(`/inventory/${props.warehouse.slug}/stock`,{onSuccess:()=>stock.reset()});const quick=(item:Item)=>{const f=useForm({quantity_on_hand:item.quantity_on_hand,quantity_reserved:item.quantity_reserved,inbound_at:item.inbound_at||'',location:item.location||'',standard_qoh:item.standard_qoh,expected_restock_qty:item.expected_restock_qty});f.patch(`/inventory/${props.warehouse.slug}/stock/${item.id}`)};const addClearance=()=>clearance.post(`/inventory/${props.warehouse.slug}/clearance`,{preserveScroll:true,onSuccess:()=>clearance.reset('product_ids')});const updateClearancePriority=(item:ClearanceProduct,event:Event)=>{const priority=Number((event.target as HTMLInputElement).value);useForm({priority}).patch(`/inventory/${props.warehouse.slug}/clearance/${item.id}`,{preserveScroll:true})};const removeClearance=(item:ClearanceProduct)=>useForm({}).delete(`/inventory/${props.warehouse.slug}/clearance/${item.id}`,{preserveScroll:true})</script>
<template><Head :title="`${warehouse.name} · BYL ERP`"/><AuthenticatedLayout :title="warehouse.name" :breadcrumbs="breadcrumbs"><section class="mvp-page"><div class="mvp-page-heading"><div><p class="mvp-kicker">Warehouse Detail</p><h2>{{warehouse.name}}</h2><p>{{warehouse.code}} · {{warehouse.country_code||'国家未填写'}} · {{warehouse.fulfillment_state_label}}<span v-if="warehouse.fulfillment_available_on"> · 预计 {{warehouse.fulfillment_available_on}} 可发货</span></p></div><div class="mvp-form-actions page-header-actions"><Link class="mvp-button" href="/inventory/products">全部产品库存</Link></div></div>
<div class="mvp-card"><h3>仓库信息</h3><form v-if="canManage" class="grid" @submit.prevent="saveMeta"><label>名称<input v-model="meta.name"></label><label>代码<input v-model="meta.code"></label><label>国家<input v-model="meta.country_code" maxlength="2"></label><label>地址1<input v-model="meta.address_line1"></label><label>地址2<input v-model="meta.address_line2"></label><label>城市<input v-model="meta.city"></label><label>州/省<input v-model="meta.state_region"></label><label>邮编<input v-model="meta.postal_code"></label><label>时区<input v-model="meta.timezone"></label><label>仓库归属<select v-model="meta.ownership_type"><option value="owned">自有仓</option><option value="external">外部仓</option></select></label><label>国内发货仓<select v-model="meta.is_domestic"><option :value="true">是</option><option :value="false">否</option></select></label><label>优先级<input v-model.number="meta.priority" type="number"></label><label>预计可发货日期<input v-model="meta.fulfillment_available_on" type="date"><small>日期未到前禁止自动分仓；日期到后仍需 Full Snapshot。</small></label><label>补货周期（天）<input v-model.number="meta.replenishment_lead_time_days" type="number" min="0" max="365" placeholder="未配置"></label><label>安全库存（天）<input v-model.number="meta.replenishment_safety_stock_days" type="number" min="0" max="365" placeholder="未配置"></label><label>目标覆盖（天）<input v-model.number="meta.replenishment_target_cover_days" type="number" min="0" max="365" placeholder="未配置"></label><label>状态<select v-model="meta.is_active"><option :value="true">启用</option><option :value="false">停用</option></select></label><button class="mvp-button mvp-button-primary">💾 保存仓库信息</button><p class="policy-hint">补货策略：补货周期 + 安全库存决定补货点；目标覆盖决定建议补货后的目标库存。三项必须同时配置。</p></form><div v-else><p>{{[warehouse.address_line1,warehouse.address_line2,warehouse.city,warehouse.state_region,warehouse.postal_code,warehouse.country_code].filter(Boolean).join(', ')||'地址未填写'}}</p></div></div>
<div class="mvp-card"><h3>服务国家/地区</h3><form v-if="canManage" class="row" @submit.prevent="saveRegions"><input v-model="regions.country_codes" placeholder="US, CA, DE"><button class="mvp-button">💾 保存</button></form><p v-else>{{warehouse.service_regions.join(', ')||'未配置'}}</p><small>仅记录真实服务范围；未配置时 Shipping 不应猜测。</small></div>
<div v-if="canOperate" class="mvp-card"><h3>增加 / 更新产品库存</h3><form class="stock-grid" @submit.prevent="addStock"><label>SKU / 产品<InventorySkuCombobox v-model="stock.sku" v-model:product-id="stock.product_id"/></label><label>当前库存<input v-model.number="stock.quantity_on_hand" type="number" min="0"></label><label>预留<input v-model.number="stock.quantity_reserved" type="number" min="0"></label><label>上架时间<input v-model="stock.inbound_at" type="date"></label><label>Location<input v-model="stock.location"></label><label>Standard QoH<input v-model.number="stock.standard_qoh" type="number" min="0"></label><label>预计备货<input v-model.number="stock.expected_restock_qty" type="number" min="0"></label><button class="mvp-button mvp-button-primary" :disabled="!stock.product_id">💾 保存库存</button></form></div>
<div class="product-tabs"><button :class="{active:productTab==='inventory'}" @click="productTab='inventory'">库存商品 <span>{{warehouse.inventories.length}}</span></button><button :class="{active:productTab==='clearance'}" @click="productTab='clearance'">清仓 / Gift 库 <span>{{clearanceProducts.length}}</span></button></div>
<div v-if="productTab==='clearance'" class="mvp-card clearance-card"><div class="clearance-heading"><div><h3>清仓 / Gift 库</h3><p>加入清仓后自动成为本仓 Gift 候选；实际是否可选始终读取实时可用库存。</p></div><span class="pool-count">{{clearanceProducts.length}} 个 SKU</span></div><form v-if="canOperate" class="clearance-add" @submit.prevent="addClearance"><div class="clearance-picker"><input v-model="clearanceQuery" placeholder="搜索本仓库存 SKU / 商品"><div class="candidate-list"><label v-for="candidate in filteredClearanceCandidates" :key="candidate.product_id"><input v-model="clearance.product_ids" type="checkbox" :value="candidate.product_id"><strong>{{candidate.sku}}</strong><span>{{candidate.name}}</span><small>可用 {{candidate.quantity_available}}</small></label><p v-if="!filteredClearanceCandidates.length" class="empty-candidates">没有可加入的本仓库存商品</p></div></div><button class="mvp-button mvp-button-primary" :disabled="!clearance.product_ids.length||clearance.processing">+ 加入清仓商品</button></form><div class="table-wrap"><table><thead><tr><th>SKU</th><th>商品</th><th>当前</th><th>预留</th><th>可用库存</th><th>Gift 优先级</th><th>状态</th><th v-if="canOperate">操作</th></tr></thead><tbody><tr v-for="item in clearanceProducts" :key="item.id"><td><strong>{{item.product.sku}}</strong></td><td>{{item.product.name}}</td><td>{{item.quantity_on_hand??'—'}}</td><td>{{item.quantity_reserved??'—'}}</td><td><strong>{{item.quantity_available??'—'}}</strong></td><td><input class="priority-input" type="number" min="1" max="9999" :value="item.priority" :disabled="!canOperate" @change="updateClearancePriority(item,$event)"></td><td><span class="clearance-status" :class="`clearance-${item.status}`">{{item.status_label}}</span></td><td v-if="canOperate"><button class="mvp-button danger" @click="removeClearance(item)">移出清仓</button></td></tr><tr v-if="!clearanceProducts.length"><td :colspan="canOperate?8:7" class="empty-pool">该仓还没有清仓商品；加入后会自动进入本仓 Gift Pool。</td></tr></tbody></table></div></div>
<div v-if="productTab==='inventory'" class="mvp-card table-wrap"><h3>仓库产品</h3><table><thead><tr><th>SKU</th><th>产品</th><th>上架时间</th><th>停留</th><th>Location</th><th>当前</th><th>预留</th><th>可用</th><th>状态</th><th>90天发货</th><th>可覆盖</th><th>建议补货</th><th>Standard QoH</th><th>预计到货</th><th v-if="canOperate">操作</th></tr></thead><tbody><tr v-for="i in warehouse.inventories" :key="i.id"><td><strong>{{i.product.sku}}</strong></td><td>{{i.product.name}}</td><td>{{i.inbound_at||'—'}}</td><td>{{i.stay_days===null?'—':`${i.stay_days} 天`}}</td><td>{{i.location||'—'}}</td><td>{{i.quantity_on_hand}}</td><td>{{i.quantity_reserved}}</td><td><strong>{{i.quantity_available}}</strong></td><td><span class="stock-badge" :class="`stock-${i.stock_status}`">{{i.stock_status_label}}</span></td><td>{{i.replenishment.shipped_90d_qty}}</td><td>{{i.replenishment.days_of_cover===null?'—':`${i.replenishment.days_of_cover} 天`}}</td><td>{{i.replenishment.recommended_restock_qty===null?i.replenishment.policy_label:`${i.replenishment.policy_label} · ${i.replenishment.recommended_restock_qty}`}}</td><td>{{i.standard_qoh??'—'}}</td><td>{{i.expected_restock_qty}}</td><td v-if="canOperate"><button class="mvp-button" @click="quick(i)">💾 Save</button></td></tr><tr v-if="!warehouse.inventories.length"><td :colspan="canOperate?15:14">暂无产品库存</td></tr></tbody></table></div>
<details class="mvp-card"><summary><strong>仓库计费表（Markdown）</strong></summary><pre class="markdown">{{billing.billing_markdown||'未填写仓库计费表'}}</pre><form v-if="canManage" @submit.prevent="saveBilling"><textarea v-model="billing.billing_markdown" rows="14" placeholder="粘贴或编辑 Markdown 文档"></textarea><button class="mvp-button mvp-button-primary">💾 保存计费表</button></form></details>
</section></AuthenticatedLayout></template>
<style scoped>.product-tabs{display:flex;gap:8px;margin:14px 0 10px}.product-tabs button{border:1px solid #dbe2e8;background:#fff;border-radius:10px;padding:9px 14px;font-weight:700;cursor:pointer}.product-tabs button.active{background:#123b2a;color:#fff;border-color:#123b2a}.product-tabs span{opacity:.7;margin-left:5px}.clearance-heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:14px}.clearance-heading h3{margin:0}.clearance-heading p{margin:5px 0 0;color:#64748b;font-size:13px}.pool-count{white-space:nowrap;background:#eef6f1;color:#174c36;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:700}.clearance-add{display:flex;gap:12px;align-items:flex-end;margin-bottom:16px}.clearance-picker{flex:1}.clearance-picker>input{width:100%;padding:9px;border:1px solid #dbe2e8;border-radius:8px;margin-bottom:8px}.candidate-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;max-height:180px;overflow:auto;border:1px solid #e5e7eb;border-radius:10px;padding:8px}.candidate-list label{display:grid;grid-template-columns:auto auto 1fr auto;gap:7px;align-items:center;padding:7px 8px;border-radius:8px;background:#f8fafc;font-size:12px}.candidate-list small{color:#64748b}.empty-candidates,.empty-pool{color:#64748b;text-align:center}.priority-input{width:76px;padding:6px;border:1px solid #dbe2e8;border-radius:7px}.clearance-status{display:inline-flex;padding:3px 8px;border-radius:999px;font-size:12px;font-weight:700}.clearance-available{background:#dcfce7;color:#166534}.clearance-out_of_stock{background:#fee2e2;color:#991b1b}.clearance-unknown{background:#f1f5f9;color:#475569}.danger{color:#991b1b}.grid,.stock-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.grid label,.stock-grid label{display:flex;flex-direction:column;gap:5px;font-size:13px}.grid input,.grid select,.stock-grid input,.row input,textarea{padding:9px;border:1px solid #dbe2e8;border-radius:8px;width:100%}.row{display:flex;gap:8px}.policy-hint{grid-column:1/-1;margin:0;color:#64748b;font-size:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap}.markdown{white-space:pre-wrap;background:#f8fafc;padding:14px;border-radius:8px;overflow:auto}details summary{cursor:pointer;margin-bottom:12px}.stock-badge{display:inline-flex;padding:3px 8px;border-radius:999px;font-size:12px;font-weight:700}.stock-out_of_stock{background:#fee2e2;color:#991b1b}.stock-low_stock{background:#ffedd5;color:#9a3412}.stock-in_stock{background:#dcfce7;color:#166534}@media(max-width:850px){.grid,.stock-grid{grid-template-columns:1fr}.clearance-add{display:block}.candidate-list{grid-template-columns:1fr}.clearance-add button{margin-top:10px}}</style>
